import{_ as e}from"./chunks/100.I7A0VXqr.js";import{_ as a,o as i,c as o,ak as n}from"./chunks/framework.DC-k2h36.js";const s="/projects/esp32Sensor/en/latest/assets/1.q48qC8aN.webp",r="/projects/esp32Sensor/en/latest/assets/2.Cp3Kpmzx.webp",l="/projects/esp32Sensor/en/latest/assets/3.BzVRz-sb.webp",d="/projects/esp32Sensor/en/latest/assets/4.BKOAPf_T.webp",f=JSON.parse('{"title":"14. Digital Tube Module","description":"","frontmatter":{},"headers":[],"relativePath":"docs/14. Digital Tube Module.md","filePath":"docs/14. Digital Tube Module.md"}'),c={name:"docs/14. Digital Tube Module.md"};function p(h,t,m,g,u,_){return i(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="_14-digital-tube-module" tabindex="-1">14. Digital Tube Module <a class="header-anchor" href="#_14-digital-tube-module" aria-label="Permalink to &quot;14. Digital Tube Module&quot;">​</a></h1><h2 id="_14-1-introduction" tabindex="-1">14.1 Introduction <a class="header-anchor" href="#_14-1-introduction" aria-label="Permalink to &quot;14.1 Introduction&quot;">​</a></h2><p>The digital tube module is an LED segment display designed to show numbers, time, speed, temperature, and simple characters. By lighting up specific LED segments on command, it provides an easy way to display real-time sensor data and project status.</p><img loading="lazy" height="1387" width="1387" src="'+s+'" class="common_img" style="width:300px;"><h2 id="_14-2-technical-specifications" tabindex="-1">14.2 Technical Specifications <a class="header-anchor" href="#_14-2-technical-specifications" aria-label="Permalink to &quot;14.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">55.4 × 23.4 × 17.2 mm</td></tr></tbody></table><h2 id="_14-3-hands-on-project" tabindex="-1">14.3 Hands-On Project <a class="header-anchor" href="#_14-3-hands-on-project" aria-label="Permalink to &quot;14.3 Hands-On Project&quot;">​</a></h2><h3 id="_14-3-1-project-overview" tabindex="-1">14.3.1 Project Overview <a class="header-anchor" href="#_14-3-1-project-overview" aria-label="Permalink to &quot;14.3.1 Project Overview&quot;">​</a></h3><p>This project uses the digital tube module to cycle through digits 1, 2, 3, and 4, pausing for 3 s on each digit. It explores how to switch between numbers in code and introduces the basics of displaying numeric data.</p><h3 id="_14-3-2-hardware-wiring" tabindex="-1">14.3.2 Hardware Wiring <a class="header-anchor" href="#_14-3-2-hardware-wiring" aria-label="Permalink to &quot;14.3.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the digital tube module to port <strong>P1</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="588" width="880" src="'+r+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This module supports connection to any port among P1, P2, P3, or P4 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h3 id="_14-3-3-adding-extensions" tabindex="-1">14.3.3 Adding Extensions <a class="header-anchor" href="#_14-3-3-adding-extensions" aria-label="Permalink to &quot;14.3.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Digital tube module</strong> under the <strong>Output module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><h3 id="_14-3-4-complete-program-and-analysis" tabindex="-1">14.3.4 Complete Program and Analysis <a class="header-anchor" href="#_14-3-4-complete-program-and-analysis" aria-label="Permalink to &quot;14.3.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Inside the main program loop, the display numbers cycle in sequence:</p><ul><li><p>Display digit 1 and wait 3 s.</p></li><li><p>Display digit 2 and wait 3 s.</p></li><li><p>Display digit 3 and wait 3 s.</p></li><li><p>Display digit 4 and wait 3 s.</p></li></ul></li><li><p>The display cycle repeats continuously.</p></li></ol><img loading="lazy" height="588" width="621" src="'+d+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">Program Files/14 Digital Tube Module.sb3</a>.</strong></p></div><h3 id="_14-3-5-program-upload" tabindex="-1">14.3.5 Program Upload <a class="header-anchor" href="#_14-3-5-program-upload" aria-label="Permalink to &quot;14.3.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+e+'" class="common_img" style="width:800px;"><h3 id="_14-3-6-implementation-outcome" tabindex="-1">14.3.6 Implementation Outcome <a class="header-anchor" href="#_14-3-6-implementation-outcome" aria-label="Permalink to &quot;14.3.6 Implementation Outcome&quot;">​</a></h3><p>Once the program upload is complete, the digital tube module cycles through digits 1, 2, 3, and 4 in sequence. Each digit stays on for 3 s before switching to the next one, demonstrating dynamic numeric display in action.</p>',25)])])}const x=a(c,[["render",p]]);export{f as __pageData,x as default};
